  //   ★ 문장도 같이 고쳤다 (build_champion_data.js 의 KEEP_TEXT — "까지" 를 뺐다).
  //     **둘은 한 쌍이라 한쪽만 되돌리면 문장이 다시 깨진다.**
  '야스오 P / CurrentCritDamage': '5%',
  '요네 P / CurrentCritDamage': '5%',

  '미스 포츈 W / LoveTapRefund': '2',
  '올라프 Q / TooltipCDRefund': '2.5',
  '사일러스 R / PerTargetCooldown': '200',
  '카타리나 E / DaggerCooldownReduction': '12 / 11 / 10 / 9 / 8',
  '애쉬 E / ChargeCooldown': '5',
  // ★ bin 5랭크 값이 9999(무제한 표식)라 화면에 "3.25 / … / 9999초" 로 나가고 있었다 (2026-08-24).
  //   롤위키 blurb "At max rank, channel duration may last indefinitely"
  '아우렐리온 솔 Q / MaxChannelDuration': '3.25 (5랭크는 무제한)',
  // ★ 자동 추출이 "최대 마나의 100% x (…)" 라는 식을 그대로 내보내던 자리 (2026-08-24).
  //   트린다미어의 자원은 분노(최대 100)다 — 접으면 롤위키 Maximum Heal 과 정확히 일치:
  //   30+0.5x100 ~ 70+2.3x100 = 80~300, 주문력 30% + 1.2%x100 = 150%.
