    //   타릭 P 가 유일한 사용처다. 인게임 툴팁엔 "재사용 대기시간이 1초 감소" 라고만
    //   적혀 있고 계수가 안 보이는데, **스킬 가속 100을 찍으면 2초로 바뀐다**
    //   (실제 규칙은 스킬 가속 10당 0.1초, 100에서 상한). 우리 값 `1 ~ 2` 가 맞다.
