// ★ 패시브 쿨타임 각주 — **인게임 툴팁 값과 실제 동작이 다른 자리** (2026-08-14).
//   우리는 인게임 툴팁을 재현하는 사이트라 **툴팁 값을 그대로 쓰되**, 각주로 실제를 알려준다.
//   지금은 니코 하나다. 나무위키가 `"클라이언트 설명에는 이유는 모르겠지만 6초로 나와 있다"`
//   고 적어 뒀고, 인게임에서 6초로 표시되는 것도 확인했다 (실제 재사용 대기시간은 2초).
//   ★ 각주 HTML 은 **홑따옴표만** 쓸 것 — 값이 큰따옴표 문자열이라 `"` 가 들어가면
//     이스케이프되고 `add_level_graphs.js` 의 줄 파싱 정규식이 통째로 깨진다.
const PASSIVE_CD_NOTE = {
    '니코': { real: '2초', why: '인게임 툴팁 표시값' },
};
const passiveCdNoteMade = [];

// ★ 우상단 값의 긴 괄호를 각주 [n] 로 접는다 (2026-08-24, 야스오 Q 지적).
//   `쿨타임 4 ~ 1.33 (추가 공격 속도 1.67%당 1% 감소, 최대 67%)` 가 한 줄에 다 나가면 너무 길다 —
//   괄호를 hover 각주로 빼서 `쿨타임 4 ~ 1.33 [1]` 로 줄인다. 쿨타임·소모값·stats 에만 적용한다 (문장 pN 은 제외).
//   ★ 남기는 괄호 셋: ① `+` 로 시작(계수 — 올라프 E 체력 소모) ② `…에 따라` 로 끝(값의 정체 —
//     레벨/충전/거리) ③ 7자 미만(눈으로 읽는 게 빠르다 — `(가속)`·`(재사용)`·`(튕김)`).
//   ★ 홑따옴표만 쓴다 — 값이 큰따옴표 문자열이라 `"` 가 들어가면 add_level_graphs 의 줄 파싱이 깨진다.
// ★★ `ctr` 은 **스킬 하나** 안에서 이어지는 각주 번호다 (2026-08-24).
//   없이 쓰면 값마다 [1] 부터 다시 세어, 한 스킬에 각주가 둘 이상일 때
//   화면에 [1] 이 여러 번 뜬다 — 야스오 Q 는 쿨타임·사거리·시전시간 셋이 전부 [1] 이었다.
//   번호 순서는 화면 순서와 같다 (쿨타임 → 소모값 → 우상단 값. index.html 의 champ-skill-meta).
function foldParenNote(val, ctr) {
    if (typeof val !== 'string' || val.includes('custom-footnote')) return val;
    let no = 0;
    return val.replace(/\s*\(([^()]+)\)/g, (m, inner) => {
        const t = inner.trim();
        // `재사용 N초` 는 길이와 무관하게 인라인 — 아무무 Q `(재사용 3초)` 는 6자라 남는데
        // 닐라 E `(재사용 0.5초)` 만 8자라 각주가 되면 재충전형끼리 들쭉날쭉해진다
        if (t.startsWith('+') || t.startsWith('재사용') || /에 따라$/.test(t) || t.length < 7) return m;
        no++;
        const shown = ctr ? ++ctr.n : no;
        return `<span class='custom-footnote'>[${shown}]<span class='custom-footnote-content'>` +
            `<div style='font-size:12px; color:#fff; white-space:nowrap;'>${t}</div></span></span>`;
    });
}

function passiveCdFootnote(no, shown, real, why) {
    return `<span class='custom-footnote'>[${no}]` +
        `<span class='custom-footnote-content'>` +
        `<div style='font-size:11px; color:#fff; margin-bottom:5px; white-space:nowrap;'>실제 재사용 대기시간</div>` +
        `<div style='font-size:12px; color:#ff9900; font-weight:bold;'>${real}</div>` +
        `<div style='font-size:10px; color:#9aa4af; margin-top:5px; white-space:nowrap;'>${shown}초는 ${why}입니다</div>` +
        `</span></span>`;
}

// ★★ 레벨 비례 **기본 피해량**만 정수로 접는다 (2026-08-14).
//   카타리나 P 가 `68.185 ~ 240.015 (레벨에 따라)` 로 나가서 읽기 불편했다 -> `68 ~ 240`.
//
//   ★★ 전역 반올림(`tidy` 에서 "소수 3자리면 정수로")을 시도했다가 **되돌렸다.**
//     두 가지가 망가진다:
//       ① **랭크별 배열이 뒤죽박죽이 된다** — 아리 Q 가
//          `105 / 118.125 / 131.25 / 144.375 / 157.5%` -> `105 / 118 / 131.25 / 144 / 157.5%`
//          로 **일부 칸만 정수**가 됐다. 한 줄 안에서 자릿수가 들쭉날쭉해 더 나쁘다
//       ② **데미지가 아닌 자리까지 바뀐다** — 브랜드 P 마나 회복, 쉔 P 쿨감,
//          신 짜오 W 미니언 배율, 그레이브즈 P **계수**(`총 공격력의 …%`)
//     그래서 자리를 표로 못 박는다. 키는 `"<한글 챔피언명> <슬롯> / <계산식 이름>"`.
//   ★ 값 **맨 앞의 `A ~ B`** 만 접는다. 뒤따르는 계수(`(+ 주문력의 70 ~ 100 …%)`)는 그대로 둔다
const ROUND_BASE_DAMAGE = new Set([
    '카타리나 P / TotalDamage',
]);
const roundBaseUsed = new Set();

// "68.185 ~ 240.015 (레벨에 따라) (+ …)" -> "68 ~ 240 (레벨에 따라) (+ …)"
function roundLeadingRange(val) {
    return String(val).replace(/^(\d+(?:\.\d+)?)\s*~\s*(\d+(?:\.\d+)?)(?=\s*\(레벨에 따라\))/,
        (all, a, b) => `${Math.round(parseFloat(a))} ~ ${Math.round(parseFloat(b))}`);
}

const statManualUsed = new Set();  // 안 쓰인 키는 오타 경고로 잡는다
const passiveCdMade = [];         // 패시브 쿨타임을 채운 곳 (bin 의 keyCooldown)
const passiveCdFail = [];         // keyCooldown 은 있는데 값을 못 푼 곳
const activeCdMade = [];          // QWER 의 keyCooldown 문장으로 쿨타임을 바꾼 곳 (2026-08-23)
const activeCdFail = [];          // QWER keyCooldown 이 있는데 못 푼 곳
const costSentence = [];          // 마나 스킬인데 소모값 문장을 그대로 쓴 곳 (2026-08-23)
// DD partype (마나/기력/…) — 소모값 문장의 @AbilityResourceName@ 을 푸는 데 쓴다
const ddPartype = (() => {
    try {
        const f = fs.readdirSync(path.join(__dirname, '.cache')).filter(x => /^dd_championFull_/.test(x)).sort().pop();
        const d = JSON.parse(fs.readFileSync(path.join(__dirname, '.cache', f), 'utf8')).data;
        const m = {};
        // ★ 여기 c.id 는 DD 의 영문 키고, 아래 루프의 c.id 는 CD 의 **숫자 id** 다. 둘 다 넣는다.
        for (const c of Object.values(d)) { m[c.id] = c.partype || ''; m[String(c.key)] = c.partype || ''; }
        return m;
    } catch (e) { return {}; }
})();
const dashMulti = [];             // 돌진 속도 후보가 둘 이상이라 건너뛴 곳
const missileSelfDropped = [];    // 자기 대상 스킬이라 투사체 속도를 뺀 곳
const missileFamilyFix = [];      // 본체 틀값을 계열 미사일 객체 값으로 바꾼 곳 (2026-08-23)
const missileFamilyMulti = [];    // 계열 후보가 여럿이라 못 고른 곳
const widthSelfDropped = [];
const widthNoDouble = [];   // 위키 폭 = mLineWidth 라 2배를 안 한 자리 (2026-08-24)      // 자기 대상 스킬이라 스킬 폭을 뺀 곳
let spellIndex = {};              // 지금 처리 중인 챔피언의 스펠 객체 색인 (buildSpellIndex)

// 툴팁 철자와 bin 철자가 어긋난 자리를 기록한다.
function noteCase(asked, actual) {
    const k = `${asked}|${actual}`;
    if (caseSeen.has(k)) return;
    caseSeen.add(k);
    if (caseList.length < 60) caseList.push(`${asked}  ->  ${actual}   (${ctx})`);
}

// DataValue 를 이름으로 찾는다. 정확히 일치가 우선, 없으면 대소문자를 무시한다.
//   ★ 계산식 안에서 다른 DataValue 를 참조할 때도 철자가 어긋난다.
//     AoeDamagePercent -> AoEDamagePercent, BonusLifesteal -> BonusLifeSteal 같은 식.
//     조각 하나가 null 이 되면 계산식이 통째로 죽으므로 여기가 제일 아프다.
// 폼이 두 개인 챔피언의 "두 번째 폼" 스킬.
//   ★ build_champion_data.js 의 FORM2 와 반드시 같아야 한다.
//     어긋나면 문장은 있는데 값이 없거나 그 반대가 된다.
//   ★ `label1` = **첫 번째 폼** 이름. 두 번째 폼 박스엔 원래부터 라벨이 있었는데
//     본체 쪽엔 없어서 "이게 어느 폼 설명이냐" 를 알 수 없었다 (2026-08-10 추가).
//     `build_champion_data.js` 의 FORM2 와 **항상 같아야 한다.**
const FORM2 = {
    Nidalee: { label: '쿠거 형태',   label1: '인간 형태',   Q: 'Takedown',         W: 'Pounce',           E: 'Swipe' },
    Elise:   { label: '거미 형태',   label1: '인간 형태',   Q: 'EliseSpiderQCast', W: 'EliseSpiderW',     E: 'EliseSpiderE' },
    Jayce:   { label: '대포 형태',   label1: '망치 형태',   Q: 'JayceShockBlast',  W: 'JayceHyperCharge', E: 'JayceAccelerationGate', R: 'JayceStanceGtH' },
    Gnar:    { label: '메가 나르',   label1: '미니 나르',   Q: 'GnarBigQ',         W: 'GnarBigW',         E: 'GnarBigE' },
    //   ★ '굴 파기' 였는데 인게임 표기가 '매복 상태' 라 맞췄다. 기본 QWE 문장은
    //     원래부터 "돌출 상태:" 로 시작한다 — 그래서 label1 도 '돌출 상태' 다
    RekSai:  { label: '매복 상태',   label1: '돌출 상태',   Q: 'RekSaiQBurrowed',  W: 'RekSaiWBurrowed',  E: 'RekSaiEBurrowed' },
    Kled:    { label: '스카를 하차', label1: '스카를 탑승', Q: 'KledRiderQ' },
};

function findSpellObj(bin, alias, objName) {
    const direct = bin[`Characters/${alias}/Spells/${objName}`];
    if (direct && direct.mSpell) return direct;
    for (const k of Object.keys(bin)) {
        if (k.endsWith('/' + objName) && bin[k] && bin[k].mSpell) return bin[k];
    }
    return null;
}

// 스킬 하나에 아이콘이 여러 개 달리는 자리 (재시전·취소·진화·1·2·3타 등).
//   bin 의 스펠 객체에 붙은 아이콘 파일 이름으로 찾는다.
//   ★ 규칙: 파일 이름이 챔피언 이름으로 시작하고, 그 뒤 첫 글자가 QWER 이고
//     바로 숫자가 따라와야 한다 (aatrox_q2, garen_e2, syndraw2 ...).
//     숫자 조건이 없으면 gragasexplosivecask 의 e, rivenwindscar 의 w 를
//     슬롯으로 오인한다.
//   ★ 다른 챔피언 에셋이 섞여 들어오므로(쓰레쉬에 Bowmaster_, 신드라에 Cryophoenix_)
//     챔피언 이름으로 시작하는 것만 받는다.
const ICON_BASE = 'https://raw.communitydragon.org/latest/game/';

// 스펠 객체에 안 붙어 있어서 위 규칙으로 못 찾는 아이콘. 파일이 실재하는 것만 적는다.
