    //   **궁 설명 옆에** 있어야 뜻이 통한다 (화면 확인 2026-08-10).
    Karma:        { karma_q2: 'R', karma_w2: 'R', karma_e2: 'R' },
    Khazix:       { khazix_q_red: 'R', khazix_w_red: 'R', khazix_e_red: 'R' },
